  "summary": "The code suffered from critical blocking I/O and SSRF vulnerabilities, alongside poor maintainability due to hardcoded configurations and lack of type safety. The refactored code introduces asynchronous processing, strict environment-based configuration, and robust error handling to ensure production readiness.",
  "fixed_code": "import os\nimport httpx\nimport asyncio\nfrom urllib.parse import urlparse\nfrom flask import Flask, abort, jsonify, request\n\napp = Flask(__name__)\napp.secret_key = os.environ.get(\"SECRET_KEY\")\nALLOWED_HOSTS = set(os.environ.get(\"ALLOWED_HOSTS\", \"api.example.com,cdn.example.com\").split(\",\"))\n\n@app.route(\"/link-preview\")\nasync def link_preview() -> flask.Response:\n    \"\"\"Fetches metadata for a given URL. Expects 'url' query parameter. Returns JSON with status and content size.\"\"\"\n    url = request.args.get(\"url\", \"\")\n    parsed = urlparse(url)\n    \n    if parsed.scheme != \"https\" or parsed.hostname not in ALLOWED_HOSTS:\n        abort(400)\n\n    try:\n        async with httpx.AsyncClient() as client:\n            resp = await client.get(url, timeout=5.0, follow_redirects=False)\n            return jsonify(status=resp.status_code, size=len(resp.content))\n    except httpx.RequestError:\n        return jsonify(error=\"Request failed\"), 502\n    except Exception:\n        return jsonify(error=\"Internal server error\"), 500"
